for lang, i in (('fr', 1), ('es', 2)):
    p = f'/app/frontend/src/cloudivr/i18n/{lang}.json'
    d = json.load(open(p))
    n = 0
    for row in T:
        if row[0] not in d:
            d[row[0]] = row[i]; n += 1
    open(p, 'w').write(json.dumps(d, ensure_ascii=False, indent=0, sort_keys=True) + '\n')
    print(lang, 'added', n)
